import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container
  const root = new Group();

  // -------------------------------------------------------------------------
  // Colors (fallback to spec defaults)
  // -------------------------------------------------------------------------
  const colors = (config.colors ||
    config.visualSpec?.colors ||
    {}) as Record<string, string>;
  const paperColor = colors.paper ?? '#e8ecf2';

  // -------------------------------------------------------------------------
  // Plane geometry – aspect based on atlas region (default 512 × 320)
  // -------------------------------------------------------------------------
  const atlasRect = config.atlasRegion?.sourceRect ?? [0, 0, 512, 320];
  const rectW = atlasRect[2];
  const rectH = atlasRect[3];
  const aspect = rectW / rectH;

  // use height = 1 unit, width scaled by aspect
  const planeWidth = aspect;
  const planeHeight = 1;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // -------------------------------------------------------------------------
  // Material – MeshBasicNodeMaterial (transparent for PNGs)
  // -------------------------------------------------------------------------
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  // -------------------------------------------------------------------------
  // Mesh
  // -------------------------------------------------------------------------
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // -------------------------------------------------------------------------
  // Load texture (async – assign when ready)
  // -------------------------------------------------------------------------
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      const texNode = texture(tex);
      material.mapNode = texNode;
      material.needsUpdate = true;
    });
  }

  // -------------------------------------------------------------------------
  // Text – render headline via font atlas
  // -------------------------------------------------------------------------
  const items =
    (config.textContent ??
      config.intent?.visualSpec?.textContent ??
      []) as Array<{
      text?: string;
      role?: string;
      typography?: { fontSize?: number };
    }>;

  const texts: any[] = [];

  for (const item of items) {
    const textObj = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 96,
      color: paperColor,
      align: 'center',
    });
    // Slightly in front of the plane to avoid Z‑fighting
    textObj.position.set(0, 0, 0.01);
    root.add(textObj);
    texts.push(textObj);
  }

  // -------------------------------------------------------------------------
  // Billboard – always face the camera
  // -------------------------------------------------------------------------
  root.onBeforeRender = (_renderer, _scene, camera) => {
    root.lookAt(camera.position);
  };

  // -------------------------------------------------------------------------
  // Event handlers container (none for this node)
  // -------------------------------------------------------------------------
  root.userData.handlers = {};

  // -------------------------------------------------------------------------
  // Cleanup – dispose resources and kill any GSAP timelines
  // -------------------------------------------------------------------------
  root.userData.cleanup = () => {
    // dispose material / geometry / texture
    if ((material as any).mapNode?.value) {
      (material as any).mapNode.value.dispose();
    }
    material.dispose();
    geometry.dispose();

    // dispose text objects
    for (const txt of texts) {
      if (txt.parent) txt.parent.remove(txt);
    }

    // kill any GSAP timelines (none created here but guard for future)
    if (root.userData._timelines) {
      for (const tl of root.userData._timelines) tl.kill();
    }
  };

  return root;
}
